    qspi_hal_set_cmd_c_cfg2(&s_lcd_spi[qspi_id].hal, 0);
    qspi_hal_force_spi_cs_low_enable(&s_lcd_spi[qspi_id].hal);
    qspi_hal_io_cpu_mem_select(&s_lcd_spi[qspi_id].hal, 1);
